/// Code74k.ts //

type Code74kEntry = {
  id: string;
  conversations: {
    from: "human" | "gpt";
    value: string;
  }[];
};

const Code74k: Code74kEntry[] = [
  {
    id: "1",
    conversations: [
      {
        from: "human",
        value:
          "Implement a Trie data structure in Java for efficient string storage and retrieval. Include a function to add a word to the Trie with its frequency. Methods for adding, searching, prefix retrieval, deletion, and frequency update are required. Handle exceptions and optimize for efficiency.",
      },
      {
        from: "gpt",
        value:
          "Below is a Trie data structure implementation in Java with added functionality for word frequency management:

```java
import java.util.*;

class TrieNode {
    private Map<Character, TrieNode> children = new HashMap<>();
    private int frequency = 0; // Word frequency counter

    public TrieNode() {}

    // Add a character to the Trie and increment frequency
    public void addChar(char c) {
        children.computeIfAbsent(c, k -> new TrieNode());
        frequency++;
    }

    // Get the child node for a given character
    public TrieNode getChild(char c) {
        return children.get(c);
    }
}

class Trie {
    private TrieNode root = new TrieNode();

    // Add a word to the Trie and update frequency
    public void addWord(String word) {
        TrieNode current = root;
        for (char c : word.toCharArray()) {
            current = current.getChild(c);
            if (current == null) {
                break;
            }
            current.addChar(c);
        }
    }

    // Search for a word in the Trie and return its frequency
    public int search(String word) {
        TrieNode current = root;
        for (char c : word.toCharArray()) {
            current = current.getChild(c);
            if (current == null) {
                return 0; // Word not found
            }
        }
        return current.frequency;
    }

    // Retrieve all words with a given prefix
    public List<String> getWordsWithPrefix(String prefix) {
        TrieNode current = root;
        for (char c : prefix.toCharArray()) {
            current = current.getChild(c);
            if (current == null) {
                return new ArrayList<>(); // No words with this prefix
            }
        }
        return buildWords(current, new StringBuilder(prefix));
    }

    private List<String> buildWords(TrieNode node, StringBuilder prefix) {
        List<String> words = new ArrayList<>();
        if (node.frequency > 0) {
            words.add(prefix.toString());
        }
        for (char c : node.children.keySet()) {
            StringBuilder newPrefix = new StringBuilder(prefix).append(c);
            words.addAll(buildWords(node.getChild(c), newPrefix));
        }
        return words;
    }

    // Delete a word from the Trie
    public void deleteWord(String word) {
        deleteWordHelper(root, word.toCharArray(), 0);
    }

    private boolean deleteWordHelper(TrieNode node, char[] word, int index) {
        if (index == word.length) {
            // Reach the end of the word, decrement frequency
            if (node.frequency > 1) {
                node.frequency--;
            } else {
                // If frequency is 1, remove this node from its parent
                char currentChar = word[index - 1];
                TrieNode parentNode = node.getChild(currentChar);
                node.children.remove(currentChar);
                if (parentNode.frequency > 1) {
                    parentNode.frequency--;
                } else {
                    deleteWordHelper(root, word, index - 1);
                }
            }
            return true;
        }

        char currentChar = word[index];
        TrieNode childNode = node.getChild(currentChar);
        if (childNode == null) {
            return false; // Word not found
        }
        if (deleteWordHelper(childNode, word, index + 1)) {
            // If the word is deleted, decrement frequency
            node.frequency--;
            return true;
        }
        return false;
    }

    // Update the frequency of a word
    public void updateFrequency(String word, int newFrequency) {
        TrieNode current = root;
        for (char c : word.toCharArray()) {
            current = current.getChild(c);
            if (current == null) {
                return; // Word not found
            }
        }
        current.frequency = newFrequency;
    }
}

// Example usage
Trie trie = new Trie();
trie.addWord("apple");
trie.addWord("appetite");
trie.addWord("apple");
System.out.println(trie.search("apple")); // Output: 2
System.out.println(trie.getWordsWithPrefix("app")); // Output: ["apple", "appetite"]
trie.deleteWord("apple");
System.out.println(trie.search("apple")); // Output: 1
trie.updateFrequency("apple", 5); // Update frequency directly
```",
