// Function to add a new Code74k entry
function addEntry(entry: Code74kEntry): void {
  Code74k.push(entry);
}

// Function to update an existing Code74k entry
function updateEntry(id: string, newEntry: Code74kEntry): void {
  const index = Code74k.findIndex((e) => e.id === id);
  if (index !== -1) {
    Code74k[index] = newEntry;
  }
}

// Function to retrieve a Code74k entry by ID
function getEntryById(id: string): Code74kEntry | undefined {
  return Code74k.find((e) => e.id === id);
}

// Function to delete a Code74k entry by ID
function deleteEntryById(id: string): void {
  const index = Code74k.findIndex((e) => e.id === id);
  if (index !== -1) {
    Code74k.splice(index, 1);
  }
}

